args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/> 
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?composer ?composerLabel ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Oru_Swakaryam dbo:musicComposer ?composer .
  OPTIONAL { ?composer dbo:deathPlace ?deathPlace . }
  OPTIONAL { ?composer rdfs:label ?composerLabel FILTER(lang(?composerLabel) = 'en') }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel) = 'en') }
}

